// Advanced prescription refill logic for {{CLINIC_NAME}}
const prescriptions = $input.all().map(item => item.json);
const today = new Date();
const refillCandidates = [];

console.log(`🔍 Checking ${prescriptions.length} prescriptions for refill eligibility`);

prescriptions.forEach(prescription => {
  try {
    // Skip if no refills remaining or status is not active
    const refillsRemaining = parseInt(prescription['Refills Remaining'] || 0);
    const status = prescription['Status'] || 'Active';

    if (refillsRemaining <= 0 || status.toLowerCase() !== 'active') {
      return;
    }

    // Parse issue date and days supply
    const issueDate = new Date(prescription['Issue Date']);
    const daysSupply = parseInt(prescription['Days Supply'] || 30);

    // Skip if issue date is invalid
    if (isNaN(issueDate.getTime()) || isNaN(daysSupply)) {
      console.warn(`⚠️ Invalid date or days supply for prescription: ${prescription['Pet Name']} - ${prescription['Medication']}`);
      return;
    }

    // Calculate days since issue and when medication runs out
    const daysSinceIssue = Math.floor((today - issueDate) / (1000 * 60 * 60 * 24));
    const medicationRunsOut = new Date(issueDate.getTime() + (daysSupply * 24 * 60 * 60 * 1000));
    const daysUntilRunsOut = Math.floor((medicationRunsOut - today) / (1000 * 60 * 60 * 24));

    // Check if refill reminder should be sent (5 days before running out)
    const shouldRemind = daysUntilRunsOut <= 5 && daysUntilRunsOut >= 0;

    if (shouldRemind) {
      console.log(`📞 Refill reminder needed for ${prescription['Pet Name']} - ${prescription['Medication']} (${daysUntilRunsOut} days remaining)`);

      refillCandidates.push({
        ...prescription,
        daysSinceIssue,
        daysUntilRunsOut,
        medicationRunsOutDate: medicationRunsOut.toLocaleDateString(),
        reminderType: daysUntilRunsOut === 0 ? 'urgent' : 'reminder'
      });
    }
  } catch (error) {
    console.error(`❌ Error processing prescription for ${prescription['Pet Name']}: ${error.message}`);
  }
});

console.log(`✅ Found ${refillCandidates.length} prescriptions requiring refill reminders`);

return refillCandidates.map(candidate => ({ json: candidate }));

